"""Parallel ChaCha20-Poly1305 implementation.

The native extension splits ChaCha20 and Poly1305 across available worker threads while
producing the standard byte-for-byte result.
"""
import fast


class Solver:
    def solve(self, problem, **kwargs):
        return fast.solve(
            problem["key"],
            problem["nonce"],
            problem["plaintext"],
            problem["associated_data"],
        )

